/**
 * D5 domestic season core: pure functions, no UI, no storage, no
 * network. Fixtures are game-generated by a seeded circle method;
 * they are NOT the real 2024-25 schedule or results.
 *
 * Determinism contract: the same (career seed, league id, season,
 * membership list) always produces byte-identical fixtures. Two
 * consecutive seasons having the same fixture order is acceptable
 * and is not a failure; no variation is required or tested.
 */

import { fnv1a32, sha256Hex } from './state-hash';
import type { SeasonData, SeasonFixture, TableRow } from './types';

/** Deterministic seed for one fixture's match simulation. */
export function fixtureSeed(
  careerSeed: number,
  leagueId: string,
  season: number,
  round: number,
  homeClubId: string,
  awayClubId: string,
): number {
  return fnv1a32(`${careerSeed}:${leagueId}:${season}:${round}:${homeClubId}:${awayClubId}`);
}

/**
 * Generate a full home-and-away round-robin. Clubs are sorted by id
 * first, so the input order can never change the output. For an even
 * club count n, rounds = 2(n-1); every club plays every other club
 * twice (once home, once away) and exactly once per round. Odd counts
 * use a bye: the bye club simply has no fixture that round.
 */
export function generateFixtures(
  clubIds: readonly string[],
  careerSeed: number,
  leagueId: string,
  season: number,
): SeasonFixture[] {
  const clubs = [...new Set(clubIds)].sort();
  if (clubs.length < 2) return [];
  const even = clubs.length % 2 === 0;
  const working = even ? [...clubs] : [...clubs, ''];
  const n = working.length;
  const halfRounds = n - 1;
  const firstHalf: SeasonFixture[] = [];
  // Circle method: first club fixed, the rest rotate each round.
  const order = [...working];
  for (let round = 1; round <= halfRounds; round += 1) {
    for (let i = 0; i < n / 2; i += 1) {
      const home = order[i];
      const away = order[n - 1 - i];
      if (!home || !away) continue;
      // Alternate home/away by round parity so no club is always home
      // in the first pairing slot across rounds.
      const swap = round % 2 === 0;
      firstHalf.push({
        round,
        homeClubId: swap ? away : home,
        awayClubId: swap ? home : away,
      });
    }
    // Rotate: keep order[0], move the last element to position 1.
    const last = order.pop();
    if (last !== undefined) order.splice(1, 0, last);
  }
  const secondHalf: SeasonFixture[] = firstHalf.map((f) => ({
    round: f.round + halfRounds,
    homeClubId: f.awayClubId,
    awayClubId: f.homeClubId,
  }));
  void careerSeed;
  void leagueId;
  void season;
  return [...firstHalf, ...secondHalf];
}

/** Fixtures of one round, in fixture order. */
export function roundFixtures(fixtures: readonly SeasonFixture[], round: number): SeasonFixture[] {
  return fixtures.filter((f) => f.round === round);
}

/** Highest round number in the fixture list, i.e. total rounds. */
export function totalRounds(fixtures: readonly SeasonFixture[]): number {
  return fixtures.reduce((max, f) => Math.max(max, f.round), 0);
}

/**
 * League table from played fixtures only. The caller supplies a
 * read-only id->name map covering the full membership list; clubs
 * with no played fixture appear at zero. Final sort is a total order
 * so it never depends on input order or device locale: points desc,
 * goal difference desc, goals for desc, club name asc by code-unit
 * comparison (not localeCompare), then club id asc for identical
 * names. A fixture referencing an unknown id falls back to the id
 * itself as its sort name; membership validation catches that case
 * upstream, so this is a defensive fallback only.
 */
export function tableFor(
  fixtures: readonly SeasonFixture[],
  clubsById: ReadonlyMap<string, string>,
): TableRow[] {
  const rows = new Map<string, TableRow>();
  for (const clubId of clubsById.keys()) {
    rows.set(clubId, {
      clubId, position: 0, played: 0, won: 0, drawn: 0, lost: 0,
      goalsFor: 0, goalsAgainst: 0, goalDifference: 0, points: 0,
    });
  }
  for (const fixture of fixtures) {
    if (!fixture.result) continue;
    const home = rows.get(fixture.homeClubId);
    const away = rows.get(fixture.awayClubId);
    if (!home || !away) continue;
    home.played += 1; away.played += 1;
    home.goalsFor += fixture.result.homeGoals;
    home.goalsAgainst += fixture.result.awayGoals;
    away.goalsFor += fixture.result.awayGoals;
    away.goalsAgainst += fixture.result.homeGoals;
    if (fixture.result.homeGoals > fixture.result.awayGoals) {
      home.won += 1; away.lost += 1; home.points += 3;
    } else if (fixture.result.homeGoals < fixture.result.awayGoals) {
      away.won += 1; home.lost += 1; away.points += 3;
    } else {
      home.drawn += 1; away.drawn += 1; home.points += 1; away.points += 1;
    }
  }
  const sorted = [...rows.values()];
  for (const row of sorted) row.goalDifference = row.goalsFor - row.goalsAgainst;
  sorted.sort((a, b) => {
    if (b.points !== a.points) return b.points - a.points;
    if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;
    if (b.goalsFor !== a.goalsFor) return b.goalsFor - a.goalsFor;
    const nameA = clubsById.get(a.clubId) ?? a.clubId;
    const nameB = clubsById.get(b.clubId) ?? b.clubId;
    if (nameA < nameB) return -1;
    if (nameA > nameB) return 1;
    if (a.clubId < b.clubId) return -1;
    if (a.clubId > b.clubId) return 1;
    return 0;
  });
  sorted.forEach((row, i) => {
    row.position = i + 1;
  });
  return sorted;
}

/** SHA-256 of the canonical played-fixture list, for cache keys. */
export function playedFixturesHash(fixtures: readonly SeasonFixture[]): string {
  const played = fixtures
    .filter((f) => f.result)
    .map((f) => [f.round, f.homeClubId, f.awayClubId, f.result!.homeGoals, f.result!.awayGoals]);
  return sha256Hex(JSON.stringify(played));
}

let tableCacheKey: string | null = null;
let tableCacheValue: TableRow[] | null = null;

/**
 * In-memory-only table cache, never persisted. Key = season,
 * league id, membership version and the played-fixtures hash, so any
 * changed result, restored save with the same played count but
 * different results, rollover, migration or adaptation change
 * produces a different key and forces a recompute. A restart clears
 * it automatically because module state is fresh.
 */
export function tableForCached(
  fixtures: readonly SeasonFixture[],
  clubsById: ReadonlyMap<string, string>,
  season: number,
  leagueId: string,
  membershipVersion: string,
): TableRow[] {
  const key = `${season}|${leagueId}|${membershipVersion}|${playedFixturesHash(fixtures)}`;
  if (tableCacheKey === key && tableCacheValue) return tableCacheValue;
  const table = tableFor(fixtures, clubsById);
  tableCacheKey = key;
  tableCacheValue = table;
  return table;
}

/** Leader's club id, or null for an empty table. */
export function championOf(table: readonly TableRow[]): string | null {
  return table.length > 0 ? table[0].clubId : null;
}

/**
 * Validate a season state. Returns human-readable issues; empty
 * means valid. Validation never repairs: a failure blocks Continue
 * (and rollover) with an error, and no guessed repair is attempted.
 */
export function validateSeasonData(data: SeasonData, membershipVersion: string): string[] {
  const issues: string[] = [];
  if (data.membershipVersion !== membershipVersion) {
    issues.push(`Membership version ${data.membershipVersion} does not match ${membershipVersion}.`);
  }
  if (data.fixtures.length === 0) issues.push('Season has no fixtures.');
  const total = totalRounds(data.fixtures);
  if (total === 0) issues.push('Season fixtures have no rounds.');
  const seenPairRound = new Set<string>();
  const perRound = new Map<number, Set<string>>();
  for (const f of data.fixtures) {
    if (f.round < 1 || f.round > total) issues.push(`Fixture round ${f.round} is out of range.`);
    const pairKey = `${f.round}|${f.homeClubId}|${f.awayClubId}`;
    if (seenPairRound.has(pairKey)) issues.push(`Duplicate fixture in round ${f.round}.`);
    seenPairRound.add(pairKey);
    const clubs = perRound.get(f.round) ?? new Set<string>();
    if (clubs.has(f.homeClubId) || clubs.has(f.awayClubId)) {
      issues.push(`A club appears twice in round ${f.round}.`);
    }
    clubs.add(f.homeClubId); clubs.add(f.awayClubId);
    perRound.set(f.round, clubs);
    if (f.result) {
      if (f.result.homeClubId !== f.homeClubId || f.result.awayClubId !== f.awayClubId) {
        issues.push(`Result club mismatch in round ${f.round}.`);
      }
    }
  }
  if (data.status === 'inProgress') {
    if (data.currentRound < 1 || data.currentRound > total) {
      issues.push(`Current round ${data.currentRound} is outside 1..${total}.`);
    }
    for (const f of data.fixtures) {
      if (f.round < data.currentRound && !f.result) issues.push(`Round ${f.round} is not fully played.`);
      if (f.round >= data.currentRound && f.result) issues.push(`Round ${f.round} is already played.`);
    }
  } else if (data.status === 'complete') {
    if (data.currentRound !== total + 1) {
      issues.push(`Complete season must have currentRound ${total + 1}, found ${data.currentRound}.`);
    }
    if (data.fixtures.some((f) => !f.result)) issues.push('Complete season has unplayed fixtures.');
    if (!data.championClubId) issues.push('Complete season has no champion recorded.');
  } else {
    issues.push(`Unknown season status ${String(data.status)}.`);
  }
  return issues;
}
